check.validation:

// Para cada doença com examesRelacionados
doenca.examesRelacionados.forEach(exame => {
  if (!loincCodes[exame.loinc]) {
    throw new Error(`LOINC ${exame.loinc} not found in ontology file`);
  }
});


const seenCodes = new Set();
diseases.forEach(d => {
  if (seenCodes.has(d.codigos.icd10)) {
    throw new Error(`Duplicate ICD-10: ${d.codigos.icd10}`);
  }
  seenCodes.add(d.codigos.icd10);
});
